private static final Map<String, String> RULE_MAPPING = new HashMap<>();
private static final Set<String> OLD_PARAM_CODES = new HashSet<>();
static {
    RULE_MAPPING.put("300101020006", "58030011");
    RULE_MAPPING.put("300101020007", "58030012");
    OLD_PARAM_CODES.add("concurrentNum");
    OLD_PARAM_CODES.add("listPicNum");
}

public boolean needTranslate(String ruleCode, Set<String> paramKeys) {
    if (RULE_MAPPING.containsKey(ruleCode)) {
        return true;
    }
    for (String key : paramKeys) {
        if (OLD_PARAM_CODES.contains(key)) {
            return true;
        }
    }
    return false;
}

public Integer translateConcurrent(Integer old) {
    // 旧 JAR 的并发数下限是 65，直接映射会让小规模请求报参数非法
    return old == null ? null : Math.max(old, CONCURRENT_FLOOR_65);
}

public Integer translateListPic(Integer old) {
    return old == null ? null : old * LIST_PIC_FACTOR_3;   // 旧口径每路 3 张
}

public Long translateHoursToSeconds(Integer hours) {
    return hours == null ? null : hours * HOURS_TO_SECONDS_3600L;
}

public CalcResult translateBack(CalcResult newResult) {
    if (newResult == null) {
        return null;
    }
    // 反向查表：新码 → 旧码，前端只认识旧码
    for (Map.Entry<String, String> e : RULE_MAPPING.entrySet()) {
        if (e.getValue().equals(newResult.getRuleCode())) {
            newResult.setRuleCode(e.getKey());
            break;
        }
    }
    // 参数同样反向换算，否则前端按旧口径显示的数值会差 3 倍或 3600 倍
    if (newResult.getDurationSeconds() != null) {
        newResult.setDurationHours(newResult.getDurationSeconds() / HOURS_TO_SECONDS_3600L);
    }
    if (newResult.getListPicNum() != null) {
        newResult.setListPicNum(newResult.getListPicNum() / LIST_PIC_FACTOR_3);
    }
    return newResult;
}
